var toggler=document.querySelector('.navbar-toggler');var menu=document.getElementById('mainNav');if(toggler&&menu){toggler.addEventListener('click',function(){var isOpen=menu.classList.toggle('show');toggler.setAttribute('aria-expanded',isOpen);});}var year=document.getElementById('year');if(year){year.textContent=new Date().getFullYear();}var mainImg=document.getElementById('mainProductImg');var thumbBtns=document.querySelectorAll('.thumb-btn');var imageModal=document.getElementById('imageModal');var modalImg=document.getElementById('modalImg');var modalCaption=document.getElementById('modalCaption');var closeBtn=document.querySelector('.lightbox-close');if(mainImg&&thumbBtns.length>0){thumbBtns.forEach(function(btn){btn.addEventListener('click',function(){thumbBtns.forEach(function(b){b.classList.remove('active');});btn.classList.add('active');var newSrc=btn.getAttribute('data-full');var thumbImg=btn.querySelector('img');if(newSrc){mainImg.src=newSrc;if(thumbImg){mainImg.alt=thumbImg.alt;}}});});if(imageModal&&modalImg){mainImg.addEventListener('click',function(){modalImg.src=mainImg.src;modalImg.alt=mainImg.alt;if(modalCaption){modalCaption.textContent=mainImg.alt;}imageModal.showModal();});if(closeBtn){closeBtn.addEventListener('click',function(){imageModal.close();});}imageModal.addEventListener('click',function(e){if(e.target===imageModal){imageModal.close();}});}}